const { DatabaseSync } = require('node:sqlite');
const path = require('path');

const DB_PATH = path.join(__dirname, 'bollywood_game.db');
const db = new DatabaseSync(DB_PATH);

// Helper function
function c(song, movie, artist, era, year, riddle1, riddle2, hindi1, hindi2, visual, music, distractors, ytid, spotifyId, fact) {
  return {
    song_name: song,
    movie_name: movie,
    artist: artist,
    era: era,
    release_year: year,
    english_riddle_1: riddle1.trim(),
    english_riddle_2: riddle2.trim(),
    hinglish_lyrics_1: hindi1.trim(),
    hinglish_lyrics_2: hindi2.trim(),
    actor_visual_clue: visual.trim(),
    music_director_clue: music.trim(),
    distractors: distractors,
    youtube_video_id: ytid || '',
    youtube_search_query: `${song} ${artist.split(',')[0].split(';')[0].trim()} ${movie} title track official video`,
    spotify_track_id: spotifyId || '',
    spotify_uri: spotifyId ? `spotify:track:${spotifyId}` : '',
    fun_fact: fact
  };
}

